import { useContext } from 'react';

import { Cache } from '@proton/shared/lib/helpers/cache';

import Context from '../containers/cache/cacheContext';

const useCache = <K = string, V = any>() => {
    const cache = useContext(Context);

    if (!cache) {
        throw new Error('Trying to use uninitialized CacheContext');
    }

    return cache as Cache<K, V>;
};

export default useCache;

export enum EXPIRATION_DAYS {
    NEVER = 'never',
    ONE = '1',
    FIFTEEN = '15',
    THIRTY = '30',
    SIXTY = '60',
    NINETY = '90',
}

export enum RESPONSE_CODE {
    SUCCESS = 1000,
    NOT_ALLOWED = 2011,
    INVALID_REQUIREMENT = 2000,
    INVALID_LINK_TYPE = 2001,
    ALREADY_EXISTS = 2500,
    NOT_FOUND = 2501,
    INVALID_ID = 2061,
}

export enum SupportedMimeTypes {
    aac = 'audio/aac',
    apk = 'application/vnd.android.package-archive',
    apng = 'image/apng',
    arc = 'application/x-freearc',
    avi = 'video/x-msvideo',
    avif = 'image/avif',
    bmp = 'image/bmp',
    bzip2 = 'application/x-bzip2',
    cr3 = 'image/x-canon-cr3',
    docx = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
export class ApiError extends Error {
    response?: Response;

    status: number;

    data?: any;

    config: any;

    constructor(message: string, status: number, name: string) {
        super(message);
        Object.setPrototypeOf(this, ApiError.prototype);
        this.status = status;
        this.name = name;
    }
}

export const createApiError = (name: string, response: Response, config: any, data?: any) => {
    const { statusText, status } = response;

    const error = new ApiError(statusText, status, name);

    error.response = response;
    error.data = data;
    error.config = config;

    return error;
};

export const serializeApiErrorData = (error: ApiError) => {
    /**
     *      We are only interested in the data here, so we strip almost everything else. In particular:
     *      * error.response is typically not serializable
     *      * error.config might not be serializable either (for instance it can include (aborted) abort controllers)
     */

    return {
        name: error.name,
        status: error.status,
        statusText: error.response?.statusText || error.message,
        data: error.data,
    };
};

export const deserializeApiErrorData = ({
    name,
    status,
    statusText,
    data,
}: ReturnType<typeof serializeApiErrorData>) => {
    const error = new ApiError(statusText, status, name);

    error.data = data;

    return error;
};

export const createOfflineError = (config: any) => {
    const error = new ApiError('No network connection', 0, 'OfflineError');
    error.config = config;
    return error;
};

export const createTimeoutError = (config: any) => {
    const error = new ApiError('Request timed out', -1, 'TimeoutError');
    error.config = config;
    return error;
};

