import createListeners, { Listeners } from './listeners';

export interface Cache<K, V> extends Pick<Listeners<[K, V | undefined], void>, 'subscribe'>, Map<K, V> {
    clearListeners: () => void;
}

/**
 * Wraps a map with support for subscribe/unsubscribe on changes.
 */
const createCache = <K, V>(map = new Map<K, V>()): Cache<K, V> => {
    const listeners = createListeners<[K, V | undefined], void>();
    return {
        get size() {
            return map.size;
        },
        forEach(callbackfn: (value: V, key: K, map: Map<K, V>) => void, thisArg?: any) {
            return map.forEach(callbackfn, thisArg);
        },
        has: (key: K) => map.has(key),
        get: (key: K) => map.get(key),
        entries: () => map.entries(),
        keys: () => map.keys(),
        values: () => map.values(),
        [Symbol.iterator]: () => map[Symbol.iterator](),
        get [Symbol.toStringTag]() {
            return map[Symbol.toStringTag];
        },
        clear: () => map.clear(),
        delete: (key: K) => {
            const r = map.delete(key);
            listeners.notify(key, undefined);
            return r;
        },
        set(key: K, value: V) {
            map.set(key, value);
            listeners.notify(key, value);
            return this;
        },
        subscribe: listeners.subscribe,
        clearListeners: listeners.clear,
    };
};

export default createCache;
import { useEffect, useState } from 'react';
import * as React from 'react';
import { useLocation } from 'react-router-dom';

import {
    AccessDeniedError,
    ErrorBoundary,
    GenericError,
    InternalServerError,
    NotFoundError,
    PrivateMainArea,
    generateUID,
} from '@proton/components';
import { HTTP_STATUS_CODE } from '@proton/shared/lib/constants';
import { RESPONSE_CODE } from '@proton/shared/lib/drive/constants';
import { ApiError } from '@proton/shared/lib/fetch/ApiError';

import useActiveShare from '../hooks/drive/useActiveShare';

interface Props {
    children: React.ReactNode;
}

const AppErrorBoundary = ({ children }: Props) => {
    const location = useLocation();
    const { setDefaultRoot } = useActiveShare();
    const [state, setState] = useState<{ id: string; error?: Error }>({
        id: generateUID('error-boundary'),
    });

    useEffect(() => {
        if (state.error) {
            setState({ id: generateUID('error-boundary') });
        }
    }, [location]);

    const handleError = (error: Error) => {
        setState((prev) => ({ ...prev, error }));
        setDefaultRoot();
    };

    const renderError = () => {
        const { error } = state;
        if (!error) {
            return null;
        }

        if (error instanceof ApiError) {
            if (error.status === HTTP_STATUS_CODE.INTERNAL_SERVER_ERROR) {
                return <InternalServerError />;
            }
            if (error.status === HTTP_STATUS_CODE.NOT_FOUND || error.data?.Code === RESPONSE_CODE.INVALID_ID) {
                return <NotFoundError />;
            }
            if (error.status === HTTP_STATUS_CODE.FORBIDDEN) {
                return <AccessDeniedError />;
            }
        }

        return <GenericError />;
    };

    return (
        <ErrorBoundary
            key={state.id}
            onError={handleError}
            component={<PrivateMainArea>{renderError()}</PrivateMainArea>}
        >
            {children}
        </ErrorBoundary>
    );
};

export default AppErrorBoundary;
export { default as useDebouncedRequest } from './useDebouncedRequest';
export { default as usePublicAuth } from './usePublicAuth';
export { default as usePublicSession, PublicSessionProvider } from './usePublicSession';
export * from './transformers';

